114	func (h *handler) replay(w http.ResponseWriter, r *http.Request) {
115		var request replayRequest
116		if err := decodeSingleJSON(r, &request); err != nil {
117			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
118			return
119		}
120		if strings.TrimSpace(request.BatchID) == "" {
121			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "batchId is required"})
122			return
123		}
124		if len(request.Samples) < 1 || len(request.Samples) > 100 {
125			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "samples must contain between 1 and 100 entries"})
126			return
127		}
128		samples := make([]Sample, len(request.Samples))
129		seenEventIDs := make(map[string]struct{}, len(request.Samples))
130		for i, entry := range request.Samples {
131			eventID := strings.TrimSpace(entry.EventID)
132			if eventID == "" {
133				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "each sample requires a non-blank eventId"})
134				return
135			}
136			if _, dup := seenEventIDs[eventID]; dup {
137				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "eventId values must be unique within a batch"})
138				return
139			}
140			seenEventIDs[eventID] = struct{}{}
141			observedAt, err := time.Parse(time.RFC3339, entry.ObservedAt)
142			if err != nil {
143				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "observedAt must be RFC3339 formatted"})
144				return
145			}
146			if len(entry.Values) == 0 || hasBlankKey(entry.Values) {
147				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "values must be a non-empty map with non-blank metric names"})
148				return
149			}
150			values, ok := metricValues(entry.Values)
151			if !ok {
152				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "values must be finite numbers"})
153				return
154			}
155			samples[i] = Sample{
156				EventID:    eventID,
157				ObservedAt: observedAt.UTC(),
158				Values:     values,
159			}
160		}
161	
162		receipt, repeat, err := h.store.Replay(r.PathValue("id"), strings.TrimSpace(request.BatchID), samples)
163		if errors.Is(err, ErrDeviceNotFound) {
164			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
165			return
166		}
167		if errors.Is(err, ErrBatchConflict) {
168			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
169			return
170		}
171		if errors.Is(err, ErrStorageUnavailable) {
172			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
173			return
174		}
175		if err != nil {
176			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
177			return
178		}
179		status := http.StatusAccepted
180		if repeat {
181			status = http.StatusOK
182		}
183		writeJSON(w, status, receipt)
184	}
185	
186	func (h *handler) history(w http.ResponseWriter, r *http.Request) {
187		id := r.PathValue("id")
188		query := r.URL.Query()
189	
190		filter := HistoryFilter{}
191		if raw := strings.TrimSpace(query.Get("from")); raw != "" {
192			from, err := time.Parse(time.RFC3339, raw)
193			if err != nil {
194				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "from must be RFC3339 formatted"})
195				return
196			}
197			filter.From = from.UTC()
198		}
199		if raw := strings.TrimSpace(query.Get("to")); raw != "" {
200			to, err := time.Parse(time.RFC3339, raw)
201			if err != nil {
202				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "to must be RFC3339 formatted"})
203				return
204			}
205			filter.To = to.UTC()
206		}
207		if !filter.From.IsZero() && !filter.To.IsZero() && filter.From.After(filter.To) {
208			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "from must not be after to"})
209			return
210		}
211	
212		limit := 20
213		if raw := strings.TrimSpace(query.Get("limit")); raw != "" {
214			value, err := strconv.Atoi(raw)
215			if err != nil || value < 1 || value > 100 {
216				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "limit must be between 1 and 100"})
217				return
218			}
219			limit = value
220		}
221	
222		var startSeq, highWater int64
223		rawCursor := strings.TrimSpace(query.Get("cursor"))
224		if rawCursor != "" {
225			// An unknown device is always 404, even with a malformed or foreign
226			// cursor; cursor problems on a registered device are 400.
227			if !h.store.Exists(id) {
228				writeJSON(w, http.StatusNotFound, map[string]string{"error": ErrDeviceNotFound.Error()})
229				return
230			}
231			cursor, err := decodeCursor(rawCursor)
232			if err != nil || cursor.DeviceID != id ||
233				!cursor.From.Equal(filter.From) || !cursor.To.Equal(filter.To) ||
234				!bytes.Equal(cursor.IID, h.store.instanceID()) {
235				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid cursor"})
236				return
237			}
238			startSeq, highWater = cursor.StartSeq, cursor.HighWater
239		}
240	
241		events, appliedBound, nextStart, hasMore, err := h.store.History(id, filter, startSeq, highWater, limit)
242		if errors.Is(err, ErrDeviceNotFound) {
243			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
244			return
245		}
246		var gone *historyGoneError
247		if errors.As(err, &gone) {
248			writeJSON(w, http.StatusGone, map[string]any{
249				"error":            ErrHistoryGone.Error(),
250				"earliestSequence": gone.earliestSequence,
251			})
252			return
253		}
254		if err != nil {
255			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
256			return
257		}
258		highWater = appliedBound
259	
260		var nextCursor any
261		if hasMore {
262			nextCursor = encodeCursor(pageCursor{
263				DeviceID:  id,
264				From:      filter.From,
265				To:        filter.To,
266				HighWater: highWater,
267				StartSeq:  nextStart,
268				IID:       h.store.instanceID(),
269			})
270		}
271	
272		writeJSON(w, http.StatusOK, map[string]any{
273			"deviceId":   id,
274			"events":     events,
275			"nextCursor": nextCursor,
276		})
277	}
278	
279	func (h *handler) snapshot(w http.ResponseWriter, _ *http.Request) {
