379	
380		// A report after the deadline conflicts.
381		reportTask(t, h, "dev-1", claim.Task.ID,
382			reportBody("rcpt-1", claim.Credential, true, "", `{"ok":true}`), http.StatusConflict)
383	
384		// The timeout released the device; after the backoff it can be claimed again.
385		*clock = clock.Add(2 * time.Second)
386		claim = claimTask(t, h, "dev-1", http.StatusOK)
387		if claim.Attempt != 2 {
388			t.Fatalf("attempt = %d, want 2", claim.Attempt)
389		}
390	}
