591			LastSeenAt time.Time `json:"lastSeenAt"`
592		}](t, doRequest(t, h, http.MethodGet, "/v1/fleet", "")).LastSeenAt
593		if !after.Equal(before) {
594			t.Fatalf("device activity time changed: %s -> %s", before, after)
595		}
596		_ = clock
597	}
598	
599	func TestTaskUnknownDeviceAndTask(t *testing.T) {
600		store, _ := newClockStore()
601		h := NewHandler(store)
602		mustRegister(t, h, "dev-1")
603	
604		claimTask(t, h, "missing", http.StatusNotFound)
605		getTask(t, h, "dev-1", 99, http.StatusNotFound)
606		cancelTask(t, h, "dev-1", 99, http.StatusNotFound)
607		reportTask(t, h, "dev-1", 99, reportBody("rcpt-1", "x", true, "", `{"ok":true}`), http.StatusNotFound)
608		r := doRequest(t, h, http.MethodGet, "/v1/devices/dev-1/tasks/99/audit", "")
609		if r.Code != http.StatusNotFound {
610			t.Fatalf("audit unknown task status = %d", r.Code)
611		}
612	}
613	
614	// Reported failures and deadline timeouts accumulate into one failure count
615	// with one set of backoff/end rules, while their timestamps, reasons and audit
616	// events stay distinct.
617	func TestTaskFailuresAccumulateAcrossSources(t *testing.T) {
618		store, clock := newClockStore()
619		h := NewHandler(store)
620		mustRegister(t, h, "dev-1")
621		createTask(t, h, "dev-1", taskBody("req-1", 1), http.StatusCreated)
622	
623		// Failure 1: device-reported; the wait runs from the receipt time.
624		claim := claimTask(t, h, "dev-1", http.StatusOK)
625		reportTask(t, h, "dev-1", claim.Task.ID,
626			reportBody("rcpt-1", claim.Credential, false, "disk full", ""), http.StatusCreated)
627		task := getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
628		if task.Status != "waiting" || task.FailureReason != "disk full" || task.Attempts != 1 {
629			t.Fatalf("after first failure: %+v", task)
630		}
631		if !task.NextClaimableAt.Equal(clock.UTC().Add(1 * time.Second)) {
632			t.Fatalf("next claimable = %s, want receipt time +1s", task.NextClaimableAt)
633		}
634		if got := store.devices["dev-1"].tasks[0].task.Failures; got != 1 {
635			t.Fatalf("failures = %d, want 1", got)
636		}
637	
638		// The waiting task does not block another already-claimable task.
639		createTask(t, h, "dev-1", taskBody("req-other", 60), http.StatusCreated)
640		other := claimTask(t, h, "dev-1", http.StatusOK)
641		if other.Task.ID != 2 {
642			t.Fatalf("claim during backoff took task %d, want 2", other.Task.ID)
643		}
644		reportTask(t, h, "dev-1", other.Task.ID,
645			reportBody("rcpt-other", other.Credential, true, "", `{"ok":true}`), http.StatusCreated)
646	
647		// Failure 2: a timeout. It takes the 2-second backoff because the failure
648		// count is shared, and the wait runs from the deadline rather than the
649		// (much later) query time.
650		*clock = clock.Add(2 * time.Second)
651		claim = claimTask(t, h, "dev-1", http.StatusOK)
652		if claim.Attempt != 2 || claim.Task.ID != 1 {
653			t.Fatalf("re-claim = %+v, want task 1 attempt 2", claim)
654		}
655		deadline2 := claim.Deadline
656		*clock = clock.Add(4 * time.Second)
657		task = getTask(t, h, "dev-1", 1, http.StatusOK)
658		if task.Status != "waiting" || task.FailureReason != "deadline exceeded" {
659			t.Fatalf("after timeout: %+v", task)
660		}
661		if !task.NextClaimableAt.Equal(deadline2.Add(2 * time.Second)) {
662			t.Fatalf("next claimable = %s, want deadline +2s (shared failure 2)", task.NextClaimableAt)
663		}
664		if got := store.devices["dev-1"].tasks[0].task.Failures; got != 2 {
665			t.Fatalf("failures = %d, want 2", got)
666		}
667		// The timed-out credential no longer authorizes a receipt.
668		reportTask(t, h, "dev-1", 1,
669			reportBody("rcpt-late", claim.Credential, true, "", `{"ok":true}`), http.StatusConflict)
670		// Repeated queries neither re-time the task nor accumulate another failure.
671		getTask(t, h, "dev-1", 1, http.StatusOK)
672		if got := store.devices["dev-1"].tasks[0].task.Failures; got != 2 {
673			t.Fatalf("repeat query changed failures to %d", got)
674		}
675		if got := len(store.devices["dev-1"].tasks[0].audit); got != 5 {
676			t.Fatalf("audit length after repeat query = %d, want 5", got)
677		}
678	
679		// Failure 3: a reported failure ends the task, stamped at receipt time.
680		claim = claimTask(t, h, "dev-1", http.StatusOK)
681		if claim.Attempt != 3 {
682			t.Fatalf("attempt = %d, want 3", claim.Attempt)
683		}
684		reportTask(t, h, "dev-1", 1,
685			reportBody("rcpt-3", claim.Credential, false, "gave up", ""), http.StatusCreated)
686		task = getTask(t, h, "dev-1", 1, http.StatusOK)
687		if task.Status != "failed" || task.CompletedAt == nil || task.Attempts != 3 {
688			t.Fatalf("after third failure: %+v", task)
689		}
690		if !task.CompletedAt.Equal(clock.UTC()) {
691			t.Fatalf("completedAt = %s, want receipt time %s", task.CompletedAt, clock.UTC())
692		}
693		claimTask(t, h, "dev-1", http.StatusNoContent)
694	
695		// The audit keeps both sources distinct, dated and ordered.
696		audit := listAudit(t, h, "dev-1", 1)
697		if got := joinEvents(eventsOf(audit)); got != "created,claimed,failed,claimed,timed_out,claimed,failed" {
698			t.Fatalf("audit events = %s", got)
699		}
700		timedOut := audit[4]
701		if timedOut.Event != "timed_out" || timedOut.At != deadline2 || timedOut.Reason != "deadline exceeded" ||
702			timedOut.Attempt != 2 || timedOut.FromStatus != "in_progress" || timedOut.ToStatus != "waiting" {
703			t.Fatalf("timeout audit record = %+v", timedOut)
704		}
705		if audit[2].At.IsZero() || audit[6].ToStatus != "failed" {
706			t.Fatalf("reported failure audit records = %+v / %+v", audit[2], audit[6])
707		}
708	}
709	
710	// An attempt is live exactly up to and including its deadline; only a strictly
711	// later instant is a timeout.
712	func TestTaskDeadlineBoundary(t *testing.T) {
713		store, _ := newClockStore()
714		h := NewHandler(store)
715		mustRegister(t, h, "dev-1")
716		createTask(t, h, "dev-1", taskBody("req-1", 5), http.StatusCreated)
717		claim := claimTask(t, h, "dev-1", http.StatusOK)
718		deadline := claim.Deadline
719	
720		// Exactly at the deadline the attempt is still in progress...
721		store.now = func() time.Time { return deadline }
722		if task := getTask(t, h, "dev-1", 1, http.StatusOK); task.Status != "in_progress" {
723			t.Fatalf("at the deadline status = %s, want in_progress", task.Status)
724		}
725		// ...and a report presented exactly then is accepted with the credential.
726		reportTask(t, h, "dev-1", 1,
727			reportBody("rcpt-1", claim.Credential, true, "", `{"ok":true}`), http.StatusCreated)
728	
729		// A strictly later instant expires a fresh attempt.
730		createTask(t, h, "dev-1", taskBody("req-2", 5), http.StatusCreated)
731		claim2 := claimTask(t, h, "dev-1", http.StatusOK)
732		store.now = func() time.Time { return claim2.Deadline.Add(time.Second) }
733		task := getTask(t, h, "dev-1", claim2.Task.ID, http.StatusOK)
734		if task.Status != "waiting" || !task.NextClaimableAt.Equal(claim2.Deadline.Add(1*time.Second)) {
735			t.Fatalf("past the deadline: %+v", task)
736		}
737	}
